package org.apache.commons.jxpath.ri.axes;

import org.apache.commons.jxpath.ri.EvalContext;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.compiler.NodeNameTest;
import org.apache.commons.jxpath.ri.compiler.NodeTest;
import org.apache.commons.jxpath.ri.model.NodeIterator;
import org.apache.commons.jxpath.ri.model.NodePointer;

/**
 * EvalContext that walks the "attribute::" axis.
 *
 * @author Dmitri Plotnikov
 * @version $Revision$ $Date$
 */
public class AttributeContext extends EvalContext {

    private NodeTest test;
    private boolean started = false;
    private NodeIterator attrIterator;
    private NodePointer currentPointer;

    /**
     * @param parentContext represents the previous step on the path
     * @param nodeTest is the name of the attribute we are looking for
     */
    public AttributeContext(EvalContext parentContext, NodeTest nodeTest) {
        super(parentContext);
        this.test = nodeTest;
    }

    public NodePointer getCurrentNodePointer() {
        return currentPointer;
    }

    public void reset() {
        started = false;
        attrIterator = null;
        super.reset();
    }

    public boolean setPosition(int position) {
        if (getCurrentPosition() > position) {
            reset();
        }

        for (; getCurrentPosition() != position;) {
            if (nextNode() == false) {
                return false;
            }
        }
        return true;
    }

    public boolean nextNode() {
        super.setPosition(1 + getCurrentPosition());
        if (started == false) {
            started = true;
            if ((nodeTestWorks()) == false) {
                return false;
            }
            QName qname = ((NodeNameTest) test).getNodeName();
            attrIterator =
                parentContext.getCurrentNodePointer().attributeIterator(qname);
        }
        if (null == attrIterator) {
            return false;
        }
        int next = attrIterator.getPosition() + 1;
        if (!attrIterator.setPosition(next)) {
            return false;
        }
        currentPointer = attrIterator.getNodePointer();
        return true;
    }

    private boolean nodeTestWorks() {
        return test instanceof NodeNameTest;
    }
}
